// =============================================================
// ADMIN DASHBOARD CHARTS
// =============================================================
// This file controls the two approval-status doughnut charts.
// The actual values come from data-* attributes generated by
// the Razor view because static JavaScript files cannot directly
// access Razor expressions such as @Model.Property.
// =============================================================


// =============================================================
// DOUGHNUT CENTER TEXT PLUGIN
// =============================================================

// Displays the total number in the center of each doughnut chart.
const doughnutCenterText = {

    id: "doughnutCenterText",

    afterDraw(chart) {

        const { ctx } = chart;

        const dataset = chart.data.datasets[0];

        if (!dataset || !dataset.data) {
            return;
        }

        // Calculate the total of Approved, Pending, and Rejected.
        const total = dataset.data.reduce(
            (sum, value) => sum + Number(value),
            0
        );

        // Find the center of the doughnut.
        const centerX =
            (chart.chartArea.left + chart.chartArea.right) / 2;

        const centerY =
            (chart.chartArea.top + chart.chartArea.bottom) / 2;

        ctx.save();

        // Total number
        ctx.font = "600 24px Arial";
        ctx.fillStyle = "#172b4d";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";

        ctx.fillText(
            total,
            centerX,
            centerY - 7
        );

        // "Total" text
        ctx.font = "400 11px Arial";
        ctx.fillStyle = "#7b8794";

        ctx.fillText(
            "Total",
            centerX,
            centerY + 14
        );

        ctx.restore();
    }
};


// =============================================================
// MARKETPLACE DOUGHNUT CHART
// =============================================================

// Get the Marketplace canvas element from the current dashboard page.
// If the element does not exist, the script stops so it does not
// cause an error on other pages that may also load this JavaScript file.
const marketplaceCanvas = document.getElementById("marketplaceChart");

if (marketplaceCanvas) {

    // dataset reads HTML data-* attributes.
    // For example, data-approved="1" becomes dataset.approved = "1".
    // Number() converts the string into a numeric value that Chart.js expects.
    const marketplaceApproved =
        Number(marketplaceCanvas.dataset.approved);

    const marketplacePending =
        Number(marketplaceCanvas.dataset.pending);

    const marketplaceRejected =
        Number(marketplaceCanvas.dataset.rejected);


    // Chart.js creates the doughnut chart using the three approval counts.
    new Chart(marketplaceCanvas, {

        // "doughnut" displays the approval counts as a doughnut chart.
        type: "doughnut",

        data: {

            // These labels identify each section of the doughnut chart.
            labels: [
                "Approved",
                "Pending",
                "Rejected"
            ],

            datasets: [{

                data: [
                    marketplaceApproved,
                    marketplacePending,
                    marketplaceRejected
                ],

                backgroundColor: [
                    "#8ACE79",
                    "#F2C94C",
                    "#E57373"
                ],  

                borderWidth: 0
            }]
        },

        options: {

            // Makes the chart automatically resize according to its container.
            responsive: true,

            // Controls the size of the hole in the middle.
            cutout: "65%",

            plugins: {

                // Places the Approved/Pending/Rejected labels below the chart.
                legend: {
                    position: "false"
                }
            }
        },

        // Register the center-text plugin for this chart.
        plugins: [
            doughnutCenterText
        ]
    });
}


// =============================================================
// LOST & FOUND DOUGHNUT CHART
// =============================================================

// Find the Lost & Found chart canvas.
const lostFoundCanvas = document.getElementById("lostFoundChart");

if (lostFoundCanvas) {

    // Read the approval counts passed from the Razor View.
    // dataset values are strings, so Number() converts them into numbers.
    const lostFoundApproved =
        Number(lostFoundCanvas.dataset.approved);

    const lostFoundPending =
        Number(lostFoundCanvas.dataset.pending);

    const lostFoundRejected =
        Number(lostFoundCanvas.dataset.rejected);


    // Create the Lost & Found approval-status doughnut chart.
    new Chart(lostFoundCanvas, {

        // Chart.js uses the doughnut type to show the proportion
        // of Approved, Pending, and Rejected reports.
        type: "doughnut",

        data: {

            // Names displayed in the chart legend.
            labels: [
                "Approved",
                "Pending",
                "Rejected"
            ],

            datasets: [{

                data: [
                    lostFoundApproved,
                    lostFoundPending,
                    lostFoundRejected
                ],

                backgroundColor: [
                    "#8ACE79",
                    "#F2C94C",
                    "#E57373"
                ],

                borderWidth: 0
            }]
        },

        options: {

            // Allows the chart to resize with its container.
            responsive: true,

            // Controls the size of the hole in the middle.
            cutout: "65%",

            plugins: {

                legend: {
                    display: false
                }
            }
        },

        // Register the center-text plugin for this chart.
        plugins: [
            doughnutCenterText
        ]
    });
}